import 'dart:async';
import 'dart:typed_data';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:share_plus/share_plus.dart';
import 'package:screenshot/screenshot.dart';
import 'domain.dart';

void main()=>runApp(const ShopApp());
class ShopApp extends StatelessWidget {
  const ShopApp({super.key});
  @override Widget build(BuildContext context)=>MaterialApp(title:'منصة المنشآت',debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,colorSchemeSeed:Colors.teal),home:const Directionality(textDirection:TextDirection.rtl,child:ShopHome()));
}
class ShopHome extends StatefulWidget {const ShopHome({super.key});@override State<ShopHome> createState()=>_ShopHomeState();}
class _ShopHomeState extends State<ShopHome> {
  ShopData data=ShopData(); bool loaded=false; int page=0;
  final screenshot=ScreenshotController();
  @override void initState(){super.initState();_load();}
  Future<void> _load() async {final p=await SharedPreferences.getInstance();final s=p.getString('shop');if(s!=null){try{data=ShopData.decode(s);}catch(_){}}setState(()=>loaded=true);}
  Future<void> save() async {final p=await SharedPreferences.getInstance();await p.setString('shop',data.encode());setState((){});}
  void msg(String s)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));
  Future<void> inputCustomer() async {
    final name=TextEditingController(),phone=TextEditingController();
    final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('إضافة عميل'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'الاسم (اختياري)')),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'الجوال (اختياري)'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('حفظ'))]));
    if(ok==true){try{data.addCustomer(DateTime.now().microsecondsSinceEpoch.toString(),name.text,phone.text);await save();msg('تمت إضافة العميل');}catch(e){msg('$e');}}
  }
  Future<void> inputSale() async {
    if(data.customers.isEmpty){msg('أضف عميلًا أولًا');return;}
    String customer=data.customers.first.id,service=services[data.activity]!.first;
    final amount=TextEditingController();
    final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,update)=>AlertDialog(title:const Text('معاملة جديدة'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(initialValue:customer,items:data.customers.map((c)=>DropdownMenuItem(value:c.id,child:Text('${c.code} - ${c.name}'))).toList(),onChanged:(v)=>update(()=>customer=v!)),DropdownButtonFormField<String>(initialValue:service,items:services[data.activity]!.map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(v)=>update(()=>service=v!)),TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'المبلغ بالريال'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('تسجيل'))])));
    if(ok==true){try{final v=double.parse(amount.text);if(!v.isFinite)throw const FormatException('مبلغ غير صالح');data.addSale(DateTime.now().microsecondsSinceEpoch.toString(),customer,service,(v*100).round());await save();msg('تم تسجيل المعاملة');}catch(e){msg('$e');}}
  }
  Future<void> inputBooking() async {
    if(data.customers.isEmpty){msg('أضف عميلًا أولًا');return;}
    String customer=data.customers.first.id,service=appointmentLabels[data.activity]!.first;
    DateTime at=DateTime.now().add(const Duration(hours:1));
    final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,update)=>AlertDialog(title:const Text('موعد جديد'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(initialValue:customer,items:data.customers.map((c)=>DropdownMenuItem(value:c.id,child:Text(c.name))).toList(),onChanged:(v)=>update(()=>customer=v!)),DropdownButtonFormField<String>(initialValue:service,items:appointmentLabels[data.activity]!.map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(v)=>update(()=>service=v!)),TextButton.icon(icon:const Icon(Icons.calendar_month),label:Text('${at.year}/${at.month}/${at.day} ${at.hour}:${at.minute.toString().padLeft(2,'0')}'),onPressed:() async {final d=await showDatePicker(context:ctx,firstDate:DateTime.now().subtract(const Duration(days:1)),lastDate:DateTime.now().add(const Duration(days:365)),initialDate:at);if(d==null||!ctx.mounted)return;final t=await showTimePicker(context:ctx,initialTime:TimeOfDay.fromDateTime(at));if(t!=null)update(()=>at=DateTime(d.year,d.month,d.day,t.hour,t.minute));})]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('حفظ'))])));
    if(ok==true){data.bookings.add(Booking(DateTime.now().microsecondsSinceEpoch.toString(),customer,service,at));await save();}
  }
  Future<void> promo() async {
    String title=promotionLabels[data.activity]!.first;
    final discount=TextEditingController(text:'20'),note=TextEditingController(text:'عرض خاص لفترة محدودة');
    final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,update)=>AlertDialog(title:const Text('بطاقة خصم'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(initialValue:title,items:promotionLabels[data.activity]!.map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(v)=>update(()=>title=v!)),TextField(controller:discount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'نسبة الخصم %')),TextField(controller:note,decoration:const InputDecoration(labelText:'عبارة العرض'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('معاينة'))])));
    if(ok!=true||!mounted)return;
    final value=int.tryParse(discount.text);if(value==null||value<1||value>100){msg('النسبة من 1 إلى 100');return;}
    await showDialog<void>(context:context,builder:(ctx)=>AlertDialog(title:const Text('بطاقة العرض'),content:SizedBox(width:320,child:Screenshot(controller:screenshot,child:Container(padding:const EdgeInsets.all(30),decoration:BoxDecoration(gradient:LinearGradient(colors:[Colors.teal.shade900,Colors.black87]),borderRadius:BorderRadius.circular(20)),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.local_offer,color:Colors.amber,size:48),const SizedBox(height:12),Text(data.shopName,style:const TextStyle(color:Colors.white,fontSize:23,fontWeight:FontWeight.bold)),const SizedBox(height:20),Text(title,style:const TextStyle(color:Colors.white,fontSize:20)),Text('$value%',style:const TextStyle(color:Colors.amber,fontSize:76,fontWeight:FontWeight.bold)),Text(note.text,textAlign:TextAlign.center,style:const TextStyle(color:Colors.white,fontSize:16)),const SizedBox(height:20),Text(activities[data.activity]!,style:const TextStyle(color:Colors.white70))])))),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('إغلاق')),FilledButton.icon(onPressed:() async {final Uint8List? bytes=await screenshot.capture(pixelRatio:3);if(bytes==null)return;await Share.shareXFiles([XFile.fromData(bytes,mimeType:'image/png',name:'discount.png')],text:'${data.shopName} - $title');},icon:const Icon(Icons.share),label:const Text('مشاركة الصورة'))]));
  }
  Future<void> backup() async {await Share.share(data.encode(),subject:'نسخة احتياطية - ${data.shopName}');}
  Future<void> restore() async {final c=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('استعادة نسخة JSON'),content:TextField(controller:c,maxLines:5,decoration:const InputDecoration(hintText:'ألصق محتوى النسخة الاحتياطية')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('استعادة'))]));if(ok==true){try{final replacement=ShopData.decode(c.text);setState(()=>data=replacement);await save();msg('تمت الاستعادة');}catch(e){msg('تعذرت الاستعادة: $e');}}}
  @override Widget build(BuildContext context){if(!loaded)return const Scaffold(body:Center(child:CircularProgressIndicator()));return Scaffold(appBar:AppBar(title:Text(data.shopName),actions:[PopupMenuButton<String>(onSelected:(v){if(v=='backup')backup();if(v=='restore')restore();},itemBuilder:(_)=>[const PopupMenuItem(value:'backup',child:Text('مشاركة نسخة احتياطية JSON')),const PopupMenuItem(value:'restore',child:Text('استعادة JSON'))])]),body:ListView(padding:const EdgeInsets.all(16),children:[if(page==0)...[Text('النشاط',style:Theme.of(context).textTheme.titleLarge),DropdownButtonFormField<String>(initialValue:data.activity,items:activities.entries.map((e)=>DropdownMenuItem(value:e.key,child:Text(e.value))).toList(),onChanged:(v)async{data.activity=v!;await save();}),TextField(decoration:InputDecoration(labelText:'اسم المنشأة',hintText:data.shopName),onSubmitted:(v)async{if(v.trim().isNotEmpty){data.shopName=v.trim();await save();}}),const SizedBox(height:20),Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(children:[Text('العملاء: ${data.customers.length}'),Text('المعاملات: ${data.sales.length}'),Text('المواعيد: ${data.bookings.length}'),Text('إجمالي المبيعات: ${(data.sales.fold<int>(0,(a,s)=>a+s.halalas)/100).toStringAsFixed(2)} ر.س')]))),Wrap(spacing:8,runSpacing:8,children:[FilledButton(onPressed:inputCustomer,child:const Text('عميل جديد')),FilledButton(onPressed:inputSale,child:const Text('معاملة')),FilledButton(onPressed:inputBooking,child:const Text('موعد')),FilledButton(onPressed:promo,child:const Text('بطاقة خصم'))])],if(page==1)...[TextField(decoration:const InputDecoration(labelText:'البحث بالاسم أو الجوال أو الرقم'),onChanged:(_)=>setState((){})),...data.customers.map((c)=>Card(child:ListTile(title:Text(c.name),subtitle:Text('${c.code} • ${c.phone??'بدون جوال'}'),trailing:Text('${data.balance(c.id)} نقطة'))))],if(page==2)...data.sales.reversed.map((s)=>Card(child:ListTile(title:Text(s.service),subtitle:Text('${(s.halalas/100).toStringAsFixed(2)} ر.س'),trailing:Text('+${s.points} نقطة')))),if(page==3)...data.bookings.reversed.map((b)=>Card(child:ListTile(title:Text(b.service),subtitle:Text('${b.at.year}/${b.at.month}/${b.at.day} ${b.at.hour}:${b.at.minute.toString().padLeft(2,'0')}'),trailing:Countdown(at:b.at)))]),bottomNavigationBar:NavigationBar(selectedIndex:page,onDestinationSelected:(i)=>setState(()=>page=i),destinations:const [NavigationDestination(icon:Icon(Icons.home),label:'الرئيسية'),NavigationDestination(icon:Icon(Icons.people),label:'العملاء'),NavigationDestination(icon:Icon(Icons.receipt),label:'المعاملات'),NavigationDestination(icon:Icon(Icons.event),label:'المواعيد')]));}
}
class Countdown extends StatefulWidget {final DateTime at;const Countdown({super.key,required this.at});@override State<Countdown> createState()=>_CountdownState();}
class _CountdownState extends State<Countdown> {Timer? timer;@override void initState(){super.initState();timer=Timer.periodic(const Duration(seconds:1),(_){if(mounted)setState((){});});}@override void dispose(){timer?.cancel();super.dispose();}@override Widget build(BuildContext context){final d=widget.at.difference(DateTime.now());if(d.isNegative)return const Text('انتهى الموعد');return Text('${d.inHours.toString().padLeft(2,'0')}:${(d.inMinutes%60).toString().padLeft(2,'0')}:${(d.inSeconds%60).toString().padLeft(2,'0')}');}}
